from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; B=ROOT/'Class 9'/'English Medium'
subjects=['English','Biology','Chemistry','ICT','Mathematics','Physical Education','Physics','Social Science I','Social Science II','Art Education','Work Education']
(ROOT/'HOME.md').write_text('''# Kerala SCERT Knowledge Vault\n\n## Current focus\n\n- [[Class 9/English Medium/Class 9 English Medium|Class 9 — English Medium]] — **complete**\n\n## Navigation\n\n- [[CLASS_INDEX]] — class and medium status\n- [[SUBJECT_INDEX]] — textbook and subject overviews\n- [[GRAPH_INDEX]] — every textbook Canvas map\n- [[Class 9/English Medium/VALIDATION_REPORT|Class 9 validation report]]\n- [[Class 9/English Medium/PROGRESS_LOG|Progress log]]\n- [[Class 9/English Medium/EDITION_AUDIT|Samagra source and edition audit]]\n- [[Class 9/English Medium/CATALOG_SCOPE|Core and choice-based catalogue scope]]\n\n## Class 9 English Medium subjects\n\n'''+''.join(f'- [[Class 9/English Medium/{s}/Subject Overview|{s}]]\n' for s in subjects),encoding='utf-8')
(ROOT/'CLASS_INDEX.md').write_text('''# Class Index\n\n| Class | Medium | Status |\n|---|---|---|\n| Class 9 | English Medium | **Complete** — 11 common subjects, all current Samagra textbooks/activity books read and validated. |\n\nThe Class 9 choice-based language catalogue is recorded separately in [[Class 9/English Medium/CATALOG_SCOPE]]. No other class or medium has been started.\n''',encoding='utf-8')
rows=['# Subject Index','','## Class 9 — English Medium','','All current common textbooks listed by the Samagra Class 9 English-medium portal have been processed. Language-reader/elective choices are separately documented in [[Class 9/English Medium/CATALOG_SCOPE]].','', '| Subject | Current title coverage | Navigation |','|---|---|---|']
details={
'English':'Reader Parts I–II','Biology':'Parts I–II','Chemistry':'Parts I–II','ICT':'Current 2025 Parts I–II; 2019 Part I retained as legacy source','Mathematics':'Parts I–II','Physical Education':'Activity Book','Physics':'Parts I–II','Social Science I':'Parts I–II','Social Science II':'Parts I–II','Art Education':'Activity Book','Work Education':'Work Integrated Education Activity Book Part I'}
for s in subjects:
 f=s.replace(' ','%20'); canvases=sorted((B/s).glob('*.canvas'))
 links=[f'[[Class 9/English Medium/{s}/Subject Overview|overview]]']+[f'[[Class 9/English Medium/{s}/{c.stem}|{c.stem}]]' for c in canvases]
 rows.append(f'| {s} | {details[s]} | '+ ' · '.join(links)+' |')
(ROOT/'SUBJECT_INDEX.md').write_text('\n'.join(rows)+'\n',encoding='utf-8')
rows=['# Graph Index','','## Class 9 — English Medium','','Each map uses Markdown file nodes. Chapter notes, concept notes and activity notes remain directly openable outside Canvas. The consistent palette is red for concepts, orange for definitions, yellow for formulas/data, green for activities, blue for chapters, and purple for meaningful cross-topic connections.','']
for s in subjects:
 rows.append(f'### {s}\n')
 for c in sorted((B/s).glob('*.canvas')):
  rows.append(f'- [[Class 9/English Medium/{s}/{c.stem}|{c.stem}]]')
(ROOT/'GRAPH_INDEX.md').write_text('\n'.join(rows)+'\n',encoding='utf-8')
readme='''# Kerala SCERT Obsidian Knowledge Vault\n\nThis `SCERT` directory is the vault root. Open this folder in Obsidian and start at [[HOME]].\n\n## Status and scope\n\nClass 9 English Medium is complete for all common subjects and current textbooks/activity books available from the Samagra portal. Choice-based language-reader offerings are documented in [[Class 9/English Medium/CATALOG_SCOPE]]. The 2019 ICT Part I source is preserved separately as a legacy file; the current 2025 Part I is processed. Other classes and mediums have not been started.\n\n## Navigation\n\n- [[HOME]] — landing page\n- [[CLASS_INDEX]] — class status\n- [[SUBJECT_INDEX]] — subject overviews\n- [[GRAPH_INDEX]] — every textbook Canvas\n- [[Class 9/English Medium/VALIDATION_REPORT]] — validation evidence and limits\n- [[Class 9/English Medium/EDITION_AUDIT]] — official source links, edition and checksums\n\n## Folder architecture\n\n`Class 9/English Medium/<Subject>/` contains the subject overview, chapter notes, substantial concept notes, definitions/formulas where useful, exercises/activities, and one Canvas per textbook. `_Source PDFs/` retains original PDFs locally. `scripts/` contains reproducible build and validation utilities. `.review/` contains temporary page renders and is excluded from Git.\n\n## Canvas colour legend\n\n| Colour | Meaning |\n|---|---|\n| `#FF6B6B` | Important concepts |\n| `#F4A261` | Definitions |\n| `#E9C46A` | Formulas and data relationships |\n| `#2A9D8F` | Examples and applications |\n| `#457B9D` | Chapters and main topics |\n| `#9B5DE5` | Cross-topic connections |\n\n## Use and source files\n\nOpen `HOME.md` in Obsidian. Canvas cards open individual Markdown notes; graph links reflect curricular relationships. Original PDFs are kept locally and excluded from Git because redistribution permission was not established. See the validation report before relying on completeness claims.\n'''
(ROOT/'README.md').write_text(readme,encoding='utf-8')
print('Navigation indexes and vault documentation updated.')
